1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block of the create-owner pipeline: rejects the request with a 409 (via
11	 * {@code DuplicateIdentityExceptionHandler}) in either of two cases.
12	 *
13	 * <ol>
14	 * <li><b>Household duplicate.</b> The household is now keyed on {@code (lastName, postcode)} through the
15	 * deterministic {@link HouseholdKey#householdId}, so an existing owner with the same household means the
16	 * new owner is a second member of it. That is rejected — <em>unless</em> the request sets
17	 * {@code sharesHousehold}, which bypasses this block so a declared household member may be created.</li>
18	 * <li><b>Identity duplicate.</b> An exact match on the whole {@link IdentityKey}
19	 * ({@code telephone|email|householdId}) is always rejected, even for a declared member: it is the same
20	 * person, not merely the same household.</li>
21	 * </ol>
22	 *
23	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail}, so the candidate's
24	 * telephone and email are already normalized. The new owner is not persisted yet, so every match found
25	 * is another owner.
26	 */
27	public class RequireUniqueIdentity {
28	
29	    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        String householdId = HouseholdKey.householdId(owner.getLastName(), owner.getPostcode());
32	        boolean sharesHousehold = Boolean.TRUE.equals(owner.getSharesHousehold());
33	        String candidate = IdentityKey.of(owner.getTelephone(), owner.getEmail(), householdId);
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (!DuplicateCandidates.isCandidate(existing)) {
36	                continue; // a soft-deleted owner no longer blocks a duplicate or identity match
37	            }
38	            if (candidate.equals(IdentityKey.ofOwner(existing))) {
39	                throw new DuplicateIdentityException(candidate);
